def _get_fix_recommendation(
    suggestions: List[Dict[str, Any]],
    similar: List[Dict[str, Any]],
) -> str:
    """Generate overall fix recommendation."""
    if suggestions and suggestions[0].get("confidence", 0) > 0.8:
        return (
            f"High confidence fix available: "
            f"{suggestions[0].get('root_cause', 'See suggestion #1')}"
        )
    elif similar and similar[0].get("success_rate", 0) > 0.9:
        return (
            f"Similar fix pattern has {similar[0]['success_rate']:.0%} success rate. "
            "Consider applying."
        )
    elif suggestions:
        return "Multiple fix hypotheses generated. Review and validate before applying."
    else:
        return "No automated fixes available. Manual investigation recommended."


