@mcp.tool()
async def list_sessions(
    limit: int = 20,
    project_id: Optional[str] = None,
) -> dict:
    """List recorded Hikaflow sessions.

    Returns recent capture sessions with metadata.  Use ``project_id`` to
    scope results to a single project.
    """
    return await _request(
        "GET",
        "/v1/sessions",
        params={"limit": limit, "project_id": project_id},
    )


@mcp.tool()
async def get_session_chunks(session_id: str) -> dict:
    """Get chunk data for a session.

    Returns the raw recorded chunks (I/O events) captured during the session.
    """
    return await _request("GET", f"/v1/sessions/{_sanitize_path_segment(session_id)}/chunks")


@mcp.tool()
async def get_session_links(session_id: str) -> dict:
    """Get shareable links for a session.

    Returns signed URLs that can be shared with colleagues for review.
    """
    return await _request("GET", f"/v1/sessions/{_sanitize_path_segment(session_id)}/links")


@mcp.tool()
async def get_run_slice(run_id: str) -> dict:
    """Get the failure slice for a run.

    The slice is a markdown summary of the execution that led to the failure,
    including relevant stack frames and variable state.
    """
    return await _request("GET", f"/v1/runs/{_sanitize_path_segment(run_id)}/artifacts/slice.md")


@mcp.tool()
async def get_replay_artifacts(run_id: str, name: str) -> dict:
    """Get a specific replay artifact by name.

    Artifacts include slice.md, divergences.json, timeline.json, and others.
    """
    return await _request("GET", f"/v1/runs/{_sanitize_path_segment(run_id)}/artifacts/{_sanitize_path_segment(name)}")


